/**
 * Watches document title and DOM changes to extract unread email count
 * and reports it to the Tauri backend to set Taskbar title, main icon, and overlay badge.
 */
(function initUnreadObserver() {
  try {
    if (window.top !== window.self) return;
  } catch (_) {
    return;
  }

  let lastReportedCount = -1;
  const BASE_ICON = 'data:image/png;base64,';

  let cachedBaseImg = null;
  function getBaseImage(callback) {
    if (cachedBaseImg) {
      callback(cachedBaseImg);
      return;
    }
    const img = new Image();
    img.onload = () => {
      cachedBaseImg = img;
      callback(img);
    };
    img.src = BASE_ICON;
  }

  function formatCountLabel(count) {
    if (count >= 1000000) {
      return Math.floor(count / 1000000) + 'M';
    }
    if (count >= 1000) {
      return Math.floor(count / 1000) + 'K';
    }
    return count.toString();
  }

  function generateBadgedIcon(baseImg, count) {
    const canvas = document.createElement('canvas');
    canvas.width = 512;
    canvas.height = 512;
    const ctx = canvas.getContext('2d');
    if (!ctx) return null;

    // 1. Draw high-resolution orange envelope icon
    ctx.drawImage(baseImg, 0, 0, 512, 512);

    if (count <= 0) {
      return Array.from(ctx.getImageData(0, 0, 512, 512).data);
    }

    // 2. Format badge text (matches Telegram taskbar badge style)
    const label = formatCountLabel(count);
    const fontSize = label.length <= 2 ? 92 : (label.length <= 3 ? 76 : 60);
    ctx.font = 'bold ' + fontSize + 'px "Segoe UI Variable Text", "Segoe UI", -apple-system, sans-serif';
    const textWidth = ctx.measureText(label).width;

    const bh = 144;
    const bw = Math.max(textWidth + 72, 144);
    const bx = 512 - bw - 12;
    const by = 8;
    const r = bh / 2;

    // 3. Soft ambient drop shadow underneath badge
    ctx.save();
    ctx.shadowColor = 'rgba(0, 0, 0, 0.32)';
    ctx.shadowBlur = 16;
    ctx.shadowOffsetY = 8;

    // 4. Vivid red pill badge (#eb4034 matching Telegram badge)
    ctx.beginPath();
    if (ctx.roundRect) {
      ctx.roundRect(bx, by, bw, bh, r);
    } else {
      ctx.arc(bx + r, by + r, r, 0, Math.PI * 2);
    }
    ctx.fillStyle = '#eb4034';
    ctx.fill();
    ctx.restore();

    // 5. Crisp centered white text
    ctx.fillStyle = '#ffffff';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(label, bx + bw / 2, by + bh / 2 + 2);

    return Array.from(ctx.getImageData(0, 0, 512, 512).data);
  }

  function generateOverlayIcon(count) {
    if (count <= 0) return null;
    const canvas = document.createElement('canvas');
    canvas.width = 64;
    canvas.height = 64;
    const ctx = canvas.getContext('2d');
    if (!ctx) return null;

    const label = formatCountLabel(count);
    const fontSize = label.length <= 1 ? 48 : (label.length <= 2 ? 38 : (label.length <= 3 ? 30 : 22));
    ctx.font = '900 ' + fontSize + 'px "Segoe UI Variable Display", "Segoe UI", -apple-system, sans-serif';

    // Charcoal Dark circle (#242424) maximized to edge with subtle high-contrast rim
    ctx.beginPath();
    ctx.arc(32, 32, 31, 0, Math.PI * 2);
    ctx.fillStyle = '#242424';
    ctx.fill();

    // Subtle high-contrast rim for dark and light taskbars
    ctx.lineWidth = 1.5;
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.28)';
    ctx.stroke();

    // Centered white text - large and prominent
    ctx.fillStyle = '#ffffff';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(label, 32, 33);

    return Array.from(ctx.getImageData(0, 0, 64, 64).data);
  }

  function extractUnreadCount() {
    // If document.title is currently holding an internal desktop command, ignore it so we don't reset count
    if (document.title.startsWith('__desktop_cmd__:')) {
      return lastReportedCount >= 0 ? lastReportedCount : 0;
    }

    // 1. Check document.title: "Inbox (66) - ...", "(255K) Inbox...", "Posteingang (4)..."
    const titleMatch = document.title.match(/\(([\d,]+|\d+[KkMm\+]?)\)/);
    if (titleMatch) {
      const raw = titleMatch[1].replace(/,/g, '');
      if (raw.endsWith('+')) {
        return parseInt(raw.slice(0, -1), 10) || 0;
      }
      if (raw.toLowerCase().endsWith('k')) {
        return Math.round(parseFloat(raw.slice(0, -1)) * 1000) || 0;
      }
      if (raw.toLowerCase().endsWith('m')) {
        return Math.round(parseFloat(raw.slice(0, -1)) * 1000000) || 0;
      }
      const num = parseInt(raw, 10);
      if (!isNaN(num)) return num;
    }

    // 2. Check sidebar inbox badge element
    const sidebarEl = document.querySelector('a[href*="#inbox"] .bsU, .aio .bsU, [data-tooltip*="Inbox"] .bsU, [aria-label*="Inbox"] .bsU, div.bsU');
    if (sidebarEl && sidebarEl.textContent) {
      const clean = sidebarEl.textContent.trim().replace(/,/g, '');
      const parsed = parseInt(clean, 10);
      if (!isNaN(parsed) && parsed >= 0) {
        return parsed;
      }
    }

    return 0;
  }

  function inspectAndReport() {
    const count = extractUnreadCount();
    if (count === lastReportedCount) return;
    const prevCount = lastReportedCount;
    lastReportedCount = count;

    // Fallback notification: if new email arrived and no web notification was dispatched recently
    if (prevCount >= 0 && count > prevCount) {
      const diff = count - prevCount;
      setTimeout(() => {
        if (Date.now() - (window.__desktop_last_notif_time || 0) > 1800) {
          try {
            const NotifClass = (typeof window !== 'undefined' && window.Notification) ? window.Notification : (typeof Notification !== 'undefined' ? Notification : null);
            if (NotifClass) {
              new NotifClass('Desktop Mail', {
                body: diff === 1 ? 'You have 1 new unread message.' : 'You have ' + diff + ' new unread messages.',
                tag: 'unread_inbox_' + count
              });
            }
          } catch (_) {}
        }
      }, 400);
    }

    // Fast, CSP-proof title command trigger for Rust backend
    try {
      const prevTitle = document.title;
      if (!prevTitle.startsWith('__desktop_cmd__:')) {
        document.title = '__desktop_cmd__:unread:' + count;
        setTimeout(() => {
          if (document.title.startsWith('__desktop_cmd__:')) {
            document.title = prevTitle;
          }
        }, 40);
      }
    } catch (_) {}

    if (window.__TAURI__ && window.__TAURI__.core) {
      if (count <= 0) {
        window.__TAURI__.core.invoke('update_unread_badge', {
          count: 0,
          iconRgba: null,
          overlayRgba: null,
          width: null,
          height: null
        }).catch(() => {});
      } else {
        getBaseImage((baseImg) => {
          try {
            const rgba = generateBadgedIcon(baseImg, count);
            const overlayRgba = generateOverlayIcon(count);
            window.__TAURI__.core.invoke('update_unread_badge', {
              count: count,
              iconRgba: rgba,
              overlayRgba: overlayRgba,
              width: 512,
              height: 512
            }).catch(() => {});
          } catch (_) {
            window.__TAURI__.core.invoke('update_unread_badge', {
              count: count,
              iconRgba: null,
              overlayRgba: null,
              width: null,
              height: null
            }).catch(() => {});
          }
        });
      }
    }
  }

  const observer = new MutationObserver(function() {
    inspectAndReport();
  });

  function attachObservers() {
    const titleEl = document.querySelector('title');
    if (titleEl) {
      try {
        observer.observe(titleEl, { childList: true, characterData: true, subtree: true });
      } catch (_) {}
    }
    if (document.body) {
      try {
        observer.observe(document.body, { childList: true, subtree: true });
      } catch (_) {}
    }
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => {
      attachObservers();
      inspectAndReport();
    });
  } else {
    attachObservers();
  }

  window.addEventListener('focus', inspectAndReport);
  document.addEventListener('visibilitychange', inspectAndReport);

  // Periodic fallback check (every 1s)
  setInterval(inspectAndReport, 1000);

  // Pre-load base image
  getBaseImage(() => {
    inspectAndReport();
  });
})();
